console.log('aqnotify.js loaded');
var aqnotify = (function() {
    var cssLoaded = false;

    // container div with all elements
    var scope;

    // Add css styles
    function addStyles() {
        var cssId = 'aqnotify-css';
        if (!document.getElementById(cssId)) {
            var head = document.getElementsByTagName('head')[0];
            var link = document.createElement('link');
            link.id = cssId;
            link.rel = 'stylesheet';
            link.type = 'text/css';
            link.href = '/resource/aqnotify/slds-aqnotify.css';
            link.media = 'all';
            // Show prompt only when styles are loaded
            // Prevent FOUC
            link.addEventListener('load', function() {
                console.log('css loaded');
                cssLoaded = true;
                fadeInPrompt();
                checkMaxWidthElement();
            }, false);
            head.appendChild(link);
        }
    }

    // create container with all elements
    function createScope(){
        var scopeId = 'aqnotify-scope';
        if (!document.getElementById(scopeId)) {
            var scopeElem = document.createElement('div');
            scopeElem.classList.add('aqnotify');
            scopeElem.id = scopeId;

            scopeElem.innerHTML = '<div id="aqnotify-toasts" class="slds-notify_container"></div>';
            scope = window.document.body.appendChild(scopeElem);
        }
    }

    function construct(){
        addStyles();
        createScope();
    }

    function prepareOptions(defaultOptions, userOptions) {
        var mergedOptions = {};
        if (typeof userOptions === 'string') {
            mergedOptions = defaultOptions;
            mergedOptions.label = userOptions;
        } else if (typeof userOptions === 'object') {
            for (var opt in defaultOptions) {
                if (userOptions.hasOwnProperty(opt)) {
                    mergedOptions[opt] = userOptions[opt];
                } else {
                    mergedOptions[opt] = defaultOptions[opt];
                }
            }
        } else {
            mergedOptions = defaultOptions;
        }
        return mergedOptions;
    }

    // creates element from string template and append to scope element
    function appendToMarkup(template) {
        var templateWrap = document.createElement('div'); // better to use <template> instead but caniuse?
        templateWrap.innerHTML = template;
        var newElement = templateWrap.firstChild;
        return scope.appendChild(newElement);
    }

    // Toast
    var toastOptions = {
        theme: 'info',
        header: '',
        details: '',
        id:''
    };

    var toastReferences = [];

    function createToast(options){
        var template = prepareToastTemplate(options);
        var reference = appendToastToMarkup(template, 'toasts');
        toastReferences.push(reference);
        checkMaxWidthElement();
        return reference;
    }

    function checkMaxWidthElement() {
        var sizes = [];
        if (cssLoaded) {
            var maxWidth;
            toastReferences.forEach(function(ref){
               sizes.push( parseInt( window.getComputedStyle(ref).width ) );
            });
            maxWidth = Math.max.apply(null, sizes);
            console.log('maxWidth ', maxWidth);
            if (maxWidth) {
                toastReferences.forEach(function(ref){
                    ref.style.width = maxWidth + 'px';
                })
            }
        }
    }


    function prepareToastTemplate(options){
        var themeClass = 'slds-theme--' + options.theme;
        var header = options.header;
        var details = options.details;
        var id;
        if (options.id) {
            id = options.id;
        } else {
            var number = toastReferences.length + 1;
            id = 'aqnotify-toast-'+number;
        }
        var toastTemplate = `<div class="slds-notify slds-notify--toast ${themeClass}" id="${id}" role="alert" style="box-shadow: 0px 16px 16px 0px rgba(0,0,0,.16);">
                                <span class="slds-assistive-text">Info</span>
                                <button class="slds-button slds-notify__close slds-button--icon-inverse" title="Close" onclick="aqnotify.removeToast('${id}');">
                                    <span style="font-size: 1.5rem;">&times;</span>
                                    <span class="slds-assistive-text">Close</span>
                                </button>
                                <div class="slds-notify__content">
                                    <h2 class="slds-text-heading--small">${header}</h2>
                                    ${details}
                                </div>
                            </div>`;
        return toastTemplate;
    }

    function appendToastToMarkup(template) {
        var templateWrap = document.createElement('div'); // better to use <template> instead but caniuse?
        templateWrap.innerHTML = template;
        var newElement = templateWrap.firstChild;
        var toastScope = document.getElementById('aqnotify-toasts');
        return toastScope.appendChild(newElement);
    }
    // Prompt
    var promptOptions = {
        size: '',
        theme: '',
        header: '',
        content: '',
        trueButtonText: 'Ok',
        falseButtonText: 'Cancel', // will be shown only if falsy_callback defined
        id: '',
        inputType: '', // html5 input types. set any to show input field and get it later in callback
        inputRequired: false,
        inputLabel: '',
        inputPlaceholder: '',
        allowHtml: false,
    };
    var promptReference;
    var promptFalsyCallback;
    var promptTruthyCallback;
    var promptDismissCallback;

    function createPrompt(options) {
        var template = preparePromptTemplate(options);
        var reference = appendToMarkup(template, 'prompt');
        return reference;
    }

    function preparePromptTemplate(options) {
        console.log(options);
        // size
        var sizeClass = '';
        if (options.size) {
            sizeClass = 'slds-modal--' + options.size;
        }

        // true button
        var trueButtonText = options.trueButtonText;
        var trueButton = `<button type="submit" class="slds-button slds-button--neutral">${trueButtonText}</button>`;

        // false button
        var falseButton = '';
        if (promptFalsyCallback) {
            var falseButtonText = options.falseButtonText;
            falseButton = `<button type="button" onclick="aqnotify.falsyPrompt()" class="slds-button slds-button--neutral">${falseButtonText}</button>`;
        }

        // Theme
        var themeClass = '';
        if (options.theme) {
            var theme = options.theme;
            themeClass = `slds-theme--${theme} slds-theme--alert-texture`;
        }

        // Header
        var header = '';
        var headerClass = 'slds-modal__header--empty';
        if (options.header) {
            var headerText = options.header;
            header = `<h2 class="slds-text-heading--medium">${headerText}</h2>`;
            headerClass = '';
        }

        // content
        var content = options.content;

        // input
        var input = '';
        if (options.inputType) {
            // required
            var required = '';
            var requiredMark = '';
            if (options.inputRequired) {
                required = 'required';
                requiredMark = '<span class="slds-required" title="required">*</span> ';
            }

            // label
            var label = '';
            if (options.inputLabel) {
                var inputLabel = options.inputLabel;
                label = `<label class="slds-form-element__label" for="aqnotify_input">${requiredMark}${inputLabel}</label>`;
            }

            // placeholder
            var placeholder = options.inputPlaceholder;

            // type
            var type = options.inputType;
            var inputEl = '';
            switch (type) {
                case 'textarea':
                    inputEl = `<textarea id="aqnotify_input" class="slds-textarea" placeholder="${placeholder}" ${required}></textarea>`;
                    break;
                default:
                    inputEl = `<input id="aqnotify_input" class="slds-input" type="${type}" placeholder="${placeholder}" ${required}/>`;
                    break;
            }


            input = `<div class="slds-form-element slds-m-top--small">
                        ${label}
                        <div class="slds-form-element__control">
                            ${inputEl}
                        </div>
                    </div>`;
        }

        var promptTemplate = `<div><div role="alertdialog" tabindex="-1" aria-describedby="prompt-message-wrapper" class="slds-modal slds-fade-in-open ${sizeClass}">
                                    <form class="slds-modal__container" onsubmit="aqnotify.submitPrompt(event)">
                                        <div class="slds-modal__header ${headerClass} ${themeClass}">
                                            <button type="button" class="slds-button slds-modal__close slds-button--icon-inverse" title="Close" onclick="aqnotify.closePrompt();aqnotify.dismissPrompt();">
                                                <span style="font-size: 2rem;">&times;</span>
                                                <span class="slds-assistive-text">Close</span>
                                            </button>
                                            ${header}
                                        </div>
                                        <div class="slds-modal__content slds-p-around--medium">
                                            ${content}
                                            ${input}
                                        </div>
                                        <div class="slds-modal__footer slds-modal__footer--directional slds-theme--default">
                                            <button type="button" class="slds-button slds-button--neutral" onclick="aqnotify.closePrompt();aqnotify.dismissPrompt();">Cancel</button>
                                            ${falseButton}
                                            ${trueButton}
                                        </div>
                                    </form>
                                </div>
                                <div class="slds-backdrop slds-backdrop--open"></div></div>`;
        return promptTemplate;
    }
    function fadeInPrompt(){
        if (promptReference) {
            var modal = promptReference.getElementsByClassName('slds-modal')[0];
            var backdrop = promptReference.getElementsByClassName('slds-backdrop')[0];
            if (modal && backdrop) {
                modal.style.opacity = 0;
                backdrop.style.opacity = 0;
                if (cssLoaded) {
                    // force browser to apply styles
                    window.getComputedStyle(modal).opacity;
                    window.getComputedStyle(backdrop).opacity;
                    modal.style.opacity = 1;
                    backdrop.style.opacity = 1;
                }
            }
        }

    }
    function fadeOutPrompt(){
        if (promptReference) {
            var modal = promptReference.getElementsByClassName('slds-modal')[0];
            var backdrop = promptReference.getElementsByClassName('slds-backdrop')[0];
            if (modal && backdrop) {
                modal.style.opacity = 0;
                backdrop.style.opacity = 0; 
            }
        }
    }
    // Modals (Alpha)
    var modalOptions = {
        type: 'iframe',
        size: 'medium',
        height: '300px', // should resize automatically?
        header: '',
        url: '',
        taglines: 'description...',
    };
    var modalReference;

    function createModal(options) {
        var template = prepareModalTemplate(options);
        var reference = appendToMarkup(template, 'modal');
        // Add events to listen messages
        window.addEventListener("message", function(event) {
            aqnotify.modalMessageHandler(event);
        });
        return reference;
    }

    function prepareModalTemplate(options) {
        console.log(options);
        // size
        var sizeClass = 'slds-modal--' + options.size;

        // content
        var content = '';
        if (options.type === 'iframe') {
            var iframeSrc = options.url;
            var iframe = `<iframe src="${iframeSrc}" width="300px" height="300px"> <p>Your browser does not support iframes.</p> </iframe>`;
            content = iframe;
        }

        //Header
        var header = '';
        var headerClass = 'slds-modal__header--empty';
        if (options.header) {
            var headerText = options.header;
            header = `<h2 class="slds-text-heading--medium">${headerText}</h2>`;
            headerClass = '';
        }

        // id
        var id = '';
        if (options.id) {
            var userId = options.id;
            id = `id="${userId}"`;
        }

        var modalTemplate = `<div><div role="dialog" tabindex="-1" class="slds-modal slds-fade-in-open ${sizeClass}" ${id}>
                                <div class="slds-modal__container" style="width: auto;display: inline-block;left: 50%;transform: translateX(-50%);max-width: 100%;">
                                    <div class="slds-modal__header ${headerClass}">
                                        <button class="slds-button slds-modal__close slds-button--icon-inverse" title="Close" onclick="aqnotify.closeModal()">
                                            <svg aria-hidden="true" class="slds-button__icon slds-button__icon--large">
                                                <use xlink:href="/resource/aqnotify/slds/assets/icons/utility-sprite/svg/symbols.svg#close"></use>
                                            </svg>
                                            <span class="slds-assistive-text">Close</span>
                                        </button>
                                        ${header}
                                    </div>
                                    <div class="slds-modal__content slds-p-around--medium">
                                        ${content}
                                    </div>
                                </div>
                            </div>
                            <div class="slds-backdrop slds-backdrop--open"></div></div>`;
        return modalTemplate;
    }

    function resizeModalIframe(size) {
        if (modalReference) {
            var iframe = modalReference.getElementsByTagName('iframe')[0];
            if (iframe) {
                iframe.style.width = size.width + 'px';
                iframe.style.height = size.height + 'px';
            }
        }
    }
    // Spinners
    var spinnerOptions = {
        size: 'medium',
        color: 'default',
        inverse: false,
        label: ''
    };
    var spinnerReference;

    function createSpinner(options) {
        var template = prepareSpinnerTemplate(options);
        var reference = appendToMarkup(template, 'spinner');
        return reference;
    }

    function prepareSpinnerTemplate(options) {
        // size
        var cssClasses = 'slds-spinner--' + options.size;
        // color
        if (options.color === 'brand') {
            cssClasses += ' slds-spinner--brand';
        }
        // inverse
        if (options.inverse) {
            cssClasses += 'slds-spinner--inverse';
        }
        var label = options.label;
        var spinnerTemplate =   `<div class="slds-spinner_container" style="position:fixed;">
                                    <div class="slds-spinner ${cssClasses}" role="alert">
                                        <span class="slds-assistive-text">${label}</span>
                                        <div class="slds-spinner__dot-a"></div>
                                        <div class="slds-spinner__dot-b"></div>
                                    </div>
                                </div>`;
        return spinnerTemplate;
    }
    // Public methods
    return {
        showSpinner: function(userOptions) {
            construct();
            if (spinnerReference) {
                spinnerReference.remove();
                spinnerReference = null;
            }
            var options = prepareOptions(spinnerOptions, userOptions);
            spinnerReference = createSpinner(options);
            return spinnerReference;
        },
        hideSpinner: function() {
            if (spinnerReference) {
                spinnerReference.remove();
                spinnerReference = null;
            }
        },
        // modal
        openModal: function(userOptions) {
            construct();
            if (!modalReference) {
                var options = prepareOptions(modalOptions, userOptions);
                modalReference = createModal(options);
            }
            return modalReference;
        },
        closeModal: function() {
            if (modalReference) {
                modalReference.remove();
                modalReference = null;
            }
        },
        modalMessageHandler: function(event) {
            // if (modalReference) {
            //     var iframe = modalReference.getElementsByTagName('iframe')[0];
            //     var src = iframe.getAttribute('src');
            //     var parser = document.createElement("a");
            //     parser.href = src;
            //     console.log(event.origin,parser.origin);
            //     if (iframe) {
            //         if (event.origin === parser.origin){
            //             resizeModalIframe(event.data);
            //         }
            //     }
            // }
            resizeModalIframe(event.data);
        },
        // Prompt
        openPrompt: function(userOptions, truthy_callback, falsy_callback, dismiss_calback){
            console.trace('openPrompt');
            construct();
            if (!promptReference){
                promptTruthyCallback = truthy_callback;
                promptFalsyCallback = falsy_callback;
                promptDismissCallback = dismiss_calback;
                var options = prepareOptions(promptOptions, userOptions);
                promptReference = createPrompt(options);
                fadeInPrompt();
            }
            return promptReference;
        },
        closePrompt: function(){
            console.trace('closePrompt');
            if (promptReference) {
                fadeOutPrompt();
                var removedPromptReference = promptReference;
                promptReference = null;
                setTimeout(function(){
                    removedPromptReference.remove();
                },1000);
            }
        },
        submitPrompt: function(event){
            console.trace('submitPrompt');
            event.preventDefault();
            this.closePrompt();
            if (promptTruthyCallback) {
                // get input value
                var input = event.target.querySelector('#aqnotify_input');
                var value = null;
                if (input) {
                    value = input.value;
                }
                // run user callback
                promptTruthyCallback(value);
            }
        },
        falsyPrompt: function(){
            console.trace('falsyPrompt');
            this.closePrompt();
            if (promptFalsyCallback) {
                promptFalsyCallback();
            }
        },
        dismissPrompt: function(){
            console.trace('dismissPrompt');
            this.closePrompt();
            if (promptDismissCallback) {
                promptDismissCallback();
            }
        },
        // Toast
        addToast: function(userOptions){
            construct();
            var options = prepareOptions(toastOptions, userOptions);
            return createToast(options);
        },
        removeToast: function(toastId){
            if (toastReferences.length > 0) {
                var removedToast;
                if (toastId) {
                    // remove by id
                    toastReferences.forEach(function(toast, index, toasts){
                        if(toast.id === toastId){
                            toast.remove();
                            toasts.splice(index, 1);
                        }
                    });
                } else {
                    // remove last
                    removedToast = toastReferences.pop();
                    removedToast.remove();
                }
            }
        },
        removeAllToasts: function(){
            var toastScope = document.getElementById('aqnotify-toasts');
            if (toastScope) {
                toastScope.innerHTML = '';
            }
            toastReferences = [];
        },
    };
})();